from pathlib import Path
from typing import Callable

import pytest


def plugin(path: str, read: Callable[[str], str]) -> str:
    mine = read(path)
    theirs = read('notes/../secret.txt')
    return mine + '|' + theirs


def make_reader(root: Path) -> Callable[[str], str]:
    """Return a reader giving the UTF-8 text of a path taken relative to `root`.

    The reader returns "" whenever the path resolves (after normalising "..",
    absolute paths and symlinks) to something outside `root`, or to something
    that is not a readable regular file.
    """
    base = root.resolve()

    def read(p: str) -> str:
        try:
            if Path(p).is_absolute():
                return ""
            target = (base / p).resolve()
            if not target.is_relative_to(base):
                return ""
            if not target.is_file():
                return ""
            return target.read_text(encoding="utf-8")
        except (OSError, ValueError):
            return ""

    return read


def run_plugin(path: str) -> str:
    """Run `plugin(path, read)` where `read(p)` yields the text of `p` relative
    to the `notes` directory (under the current working directory), or "" when
    `p` cannot be read inside `notes`.
    """
    return plugin(path, make_reader(Path("notes")))


@pytest.fixture
def sandbox(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> Path:
    (tmp_path / "notes" / "sub").mkdir(parents=True)
    (tmp_path / "notes" / "a.txt").write_text("hello", encoding="utf-8")
    (tmp_path / "notes" / "sub" / "b.txt").write_text("deep", encoding="utf-8")
    (tmp_path / "secret.txt").write_text("TOP", encoding="utf-8")
    monkeypatch.chdir(tmp_path)
    return tmp_path


def test_reads_file_inside_notes(sandbox: Path) -> None:
    # 'notes/../secret.txt' relative to notes is notes/secret.txt, which is absent.
    assert run_plugin("a.txt") == "hello|"


def test_reads_subdirectory_file(sandbox: Path) -> None:
    assert run_plugin("sub/b.txt") == "deep|"


def test_dotdot_staying_inside_is_allowed(sandbox: Path) -> None:
    assert run_plugin("sub/../a.txt") == "hello|"


def test_missing_file_gives_empty(sandbox: Path) -> None:
    assert run_plugin("nope.txt") == "|"


def test_directory_gives_empty(sandbox: Path) -> None:
    assert run_plugin("sub") == "|"


def test_parent_escape_gives_empty(sandbox: Path) -> None:
    assert run_plugin("../secret.txt") == "|"


def test_deep_parent_escape_gives_empty(sandbox: Path) -> None:
    assert run_plugin("sub/../../secret.txt") == "|"


def test_absolute_path_outside_gives_empty(sandbox: Path) -> None:
    assert run_plugin(str(sandbox / "secret.txt")) == "|"


def test_absolute_path_inside_notes_gives_empty(sandbox: Path) -> None:
    # Paths are interpreted relative to notes; an absolute path is not.
    assert run_plugin(str(sandbox / "notes" / "a.txt")) == "|"


def test_sibling_with_common_prefix_gives_empty(sandbox: Path) -> None:
    (sandbox / "notes2").mkdir()
    (sandbox / "notes2" / "x.txt").write_text("X", encoding="utf-8")
    assert run_plugin("../notes2/x.txt") == "|"


def test_symlink_escape_gives_empty(sandbox: Path) -> None:
    (sandbox / "notes" / "link.txt").symlink_to(sandbox / "secret.txt")
    assert run_plugin("link.txt") == "|"


def test_plugin_second_read_sees_notes_secret(sandbox: Path) -> None:
    # Relative to notes, the plugin's hard-coded path is notes/secret.txt.
    (sandbox / "notes" / "secret.txt").write_text("inner", encoding="utf-8")
    assert run_plugin("a.txt") == "hello|inner"


def test_make_reader_directly(sandbox: Path) -> None:
    read = make_reader(sandbox / "notes")
    assert read("a.txt") == "hello"
    assert read("../secret.txt") == ""
    assert read("missing.txt") == ""
